+        if (i == 8 || i == 13 || i == 18 || i == 23) {
+            if (ch != L'-') return false;
+            continue;
+        }
+        if (!((ch >= L'0' && ch <= L'9')
+              || (ch >= L'a' && ch <= L'f')
+              || (ch >= L'A' && ch <= L'F'))) {
+            return false;
