+    if (ResumeThread(thread.get()) == static_cast<DWORD>(-1)) {
+        return preResumeFailure(
+            "BROKER_RESUME_FAILED",
+            GetLastError(),
+            process.get(),
+            true);
+    }
+    thread.reset();
