+std::string canonicalJwk(std::string_view x, std::string_view y) {
+    return std::string("{\"crv\":\"P-256\",\"ext\":true,\"key_ops\":[\"verify\"],\"kty\":\"EC\",\"x\":\"")
+        + std::string(x) + "\",\"y\":\"" + std::string(y) + "\"}";
